        code: "<div id=\"sample\">\n  텍스트\n  <span>span</span>\n  <!-- 주석 -->\n</div>\n// Chrome 156\nsample.childNodes.length                 // 5     [텍스트, 요소, 텍스트, 주석, 텍스트]\nsample.children.length                   // 1\n[...sample.childNodes].map(n => n.nodeType)   // [3, 1, 3, 8, 3]\n\n// 살아 있는 vs 정적\nconst live = d.getElementsByTagName('i'), stat = d.querySelectorAll('i');   // 각 1\nd.appendChild(document.createElement('i'));\n[live.length, stat.length]               // [2, 1]\n\n// innerHTML vs textContent\nd1.innerHTML = '<b>굵게</b>';   d1.children.length   // 1       파싱해 요소가 됐다\nd2.textContent = '<b>굵게</b>'; d2.innerHTML         // '&lt;b&gt;굵게&lt;/b&gt;'   글자 그대로 (XSS 안전)\n\n// innerHTML += 는 전부 다시 파싱\nd.innerHTML = '<input value=x>'; d.firstChild.value = '사용자가 친 값';\nd.innerHTML += '<span></span>';  d.firstChild.value   // 'x'   ← 입력이 사라졌다\n\n// append 는 옮긴다\np.append(c); q.append(c); [p.children.length, q.children.length]   // [0, 1]\n// cloneNode(true) 는 리스너를 복사하지 않는다: 복제본 dispatch → 리스너 호출 0, 원본 → 1",
