        code: "// 위임하려면\nform.addEventListener('focusin', e => e.target.classList.add('focused'));     // focusin 은 버블한다\nform.addEventListener('focusout', e => e.target.classList.remove('focused'));\n// 또는\nform.addEventListener('focus', handler, { capture: true });                     // 캡처는 버블과 무관하다\n\n// 프로그램 변경은 이벤트가 없다 (실제로 돌려 보면 직접 보내야 했다)\ninput.value = 'x';                                        // input · change 이벤트 없음\ninput.dispatchEvent(new Event('input', { bubbles: true }));   // 다른 리스너에 알리려면 직접\n\n// input 에서는 막을 수 없다 — 이미 바뀌었다\ninput.addEventListener('input', e => { e.preventDefault(); });   // 효과 없음\ninput.addEventListener('input', e => { input.value = input.value.replace(/\\D/g, ''); });   // 고쳐 쓴다\n\n// 클립보드\ninput.addEventListener('paste', e => { const text = e.clipboardData.getData('text/plain'); /* 검사 */\n  e.preventDefault(); });",
