        code: "// 동적 스크립트\nfunction loadScript(src) {\n  return new Promise((resolve, reject) => {\n    const s = document.createElement('script');\n    s.src = src;\n    s.onload = () => resolve(s);                        // 받고 실행까지 끝난 뒤\n    s.onerror = () => reject(new Error(`${src} 로드 실패`));   // 404·네트워크. 안의 실행 에러는 아니다\n    document.head.append(s);                             // async 기본. 순서가 필요하면 s.async = false\n  });\n}\n\n// 실행 에러는 window.onerror 로 — 교차 출처면 'Script error.'\nwindow.onerror = (message, url, line, col, error) => {};\n// + 서버의 Access-Control-Allow-Origin → 자세한 에러\n<script src=\"https://cdn.example/lib.js\" crossorigin=\"anonymous\"></script>\n\n// 이미지 — src 를 넣으면 로드 시작 (DOM 밖에서도)\nconst img = new Image(); img.onload = () => img.naturalWidth; img.src = url;\n\n// iframe — onload 만. onerror 없음. 교차 출처 안의 에러는 못 본다",
