        code: "// Chrome 156\nconst mo = new MutationObserver(recs => log(`콜백 1번, 기록 ${recs.length}개`));\nmo.observe(d, { attributes: true, childList: true, subtree: true, characterData: true });\nd.setAttribute('a', '1'); d.append(el); d.className = 'x';\nlog('동기 코드 끝 (콜백 아직)');\n// → '동기 코드 끝 (콜백 아직)' → '콜백 1번, 기록 3개: attributes:a, childList, attributes:class'\n\n// Range\nconst r = document.createRange(); r.selectNodeContents(p);\n{ text: '선택할 문장입니다', rects: 1, collapsed: false }\n\n// Selection — 프로그램으로 고르기\nr.setStart(p.firstChild, 0); r.setEnd(p.firstChild, 3);\nconst s = document.getSelection(); s.removeAllRanges(); s.addRange(r);\n{ selected: '선택할', rangeCount: 1, anchorOffset: 0, focusOffset: 3 }\n\n// 이벤트 루프 (11장 · 렌더링 10장의 측정)\nsync → then1 → micro → then2 → timeout      /      마이크로태스크 셋 → setTimeout 0 → requestAnimationFrame",
