        code: "// 반복\n'aaa'.match(/a{2}/)[0]                   // 'aa'\n'\"a\" and \"b\"'.match(/\".+\"/)[0]          // '\"a\" and \"b\"'      탐욕: 최대한 먹고 뒤에서 줄인다\n'\"a\" and \"b\"'.match(/\".+?\"/g)           // ['\"a\"', '\"b\"']     게으름: 최소한 먹고 뒤에서 늘린다\n\n// 묶기\nconst m = '2026-11-12'.match(/(?<y>\\d{4})-(?<m>\\d{2})-(?<d>\\d{2})/);\n[m[1], m.groups.y, m.groups.d]           // ['2026', '2026', '12']\n[...'a1 b2'.matchAll(/(\\w)(\\d)/g)].map(m => m.slice(1))   // [['a', '1'], ['b', '2']]\n/([\"'])(.*?)\\1/.exec('\"q\" and \\'z\\'')[0]   // '\"q\"'            역참조: 같은 따옴표\n'html css js'.match(/html|css|java(script)?/g)   // ['html', 'css']\n\n// 조건 (소비하지 않음)\n'1 turkey costs 30€'.match(/\\d+(?=€)/)[0]      // '30'\n'1 turkey costs $30'.match(/(?<=\\$)\\d+/)[0]    // '30'\n'2 turkeys cost 60€'.match(/\\d+\\b(?!€)/g)      // ['2']\n\n// 메서드\n'John Smith'.replace(/(\\w+) (\\w+)/, '$2, $1')           // 'Smith, John'\n'John Smith'.replace(/(?<f>\\w+) (?<l>\\w+)/, '$<l> $<f>')  // 'Smith John'\n'a1b2'.replace(/\\d/g, d => d * 2)                        // 'a2b4'\n'aa'.replaceAll(/a/, 'b')                                // TypeError: … called with a non-global\n                                                         RegExp argument\nnew RegExp('\\\\d+', 'g').source  ·  String.raw`\\d+`       // '\\d+' · '\\d+'\n/[\\p{L}--[a-z]]/v.test('A') / .test('a')                 // true / false  (v: 집합 연산)",
